const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(n,size=17)=>ICONS[n].replace('width="18" height="18"',`width="${size}" height="${size}"`);
const names=['林同学','陈同学','苏同学','周同学','许同学','唐同学','赵同学','顾同学'];
const states={pending:'待提交',returned:'待修改',review:'待验收',done:'已完成'};
const baseTasks=[
{id:1,title:'需求分析 · 个人报告',course:'软件工程',date:'11月08日 23:59',shortDate:'今天 23:59',due:'2026-11-08T23:59',soon:true,publisher:'陈同学',description:'结合小组已确定的选题，独立完成自己负责模块的需求分析。重点说明用户是谁、问题是什么，以及系统如何解决问题。',requirements:['说明负责模块的目标用户、业务场景和功能边界。','绘制一张用例图，补充至少三个核心用例的文字描述。','提交 PDF，建议 3–5 页；文件名为「姓名_需求分析」。'],attachment:'个人需求分析_写作模板.docx',fileType:'PDF',statuses:['pending','review','done','review','pending','done','returned','review']},
{id:2,title:'数据库 E-R 图设计',course:'数据库原理',date:'11月09日 18:00',shortDate:'明天 18:00',due:'2026-11-09T18:00',publisher:'陈同学',description:'为自己的课程项目建立概念数据模型，说明实体、属性和实体之间的联系。',requirements:['至少包含五个实体，并标明主键与联系基数。','说明多对多关系的处理方式。','提交设计说明 PDF 和可编辑的图源文件。'],attachment:'E-R图设计_要求.pdf',fileType:'PDF / DRAWIO',feedback:'请补充「选课」关系的基数，并在说明中解释联合主键的选择。修改后重新提交即可。',statuses:['returned','done','review','pending','review','done','review','pending']},
{id:3,title:'进程调度算法实验',course:'操作系统',date:'11月10日 23:59',shortDate:'11月10日',due:'2026-11-10T23:59',publisher:'陈同学',description:'实现并比较先来先服务与时间片轮转两种调度算法，用同一组输入记录调度结果。',requirements:['提交可运行源码与实验报告。','列出每个进程的周转时间与平均等待时间。','附运行截图，并说明时间片大小对结果的影响。'],attachment:'调度算法_实验说明.pdf',fileType:'PDF / ZIP',statuses:['review','review','pending','done','review','pending','done','returned']},
{id:4,title:'本周论文阅读记录',course:'科研训练',date:'11月12日 20:00',shortDate:'11月12日',due:'2026-11-12T20:00',publisher:'陈同学',description:'选读一篇与当前研究方向有关的论文，用自己的语言概括问题、方法和局限。',requirements:['写明论文标题、出处与阅读链接。','用 500–800 字概括主要方法和一处可改进之处。','可直接填写文字，也可提交 PDF 阅读笔记。'],attachment:'论文阅读_记录模板.pdf',fileType:'文字 / PDF',statuses:['pending','pending','done','review','pending','review','done','returned']},
{id:5,title:'软件工程 · 选题说明',course:'软件工程',date:'11月05日 23:59',shortDate:'11月05日',due:'2026-11-05T23:59',publisher:'陈同学',description:'独立描述一个你想解决的真实问题，为课程设计选题提供依据。',requirements:['明确问题发生的场景和目标人群。','列出三个核心功能与现有方案的差异。','提交一页选题说明 PDF。'],attachment:'选题说明_参考格式.pdf',fileType:'PDF',feedback:'问题定义清楚，功能边界合理。后续需求分析可以继续细化异常场景。',statuses:['done','done','done','done','done','done','done','done']},
{id:6,title:'个人开发环境检查',course:'课程准备',date:'11月11日 18:00',shortDate:'11月11日',due:'2026-11-11T18:00',publisher:'陈同学',description:'确认本地开发环境可用，并记录依赖版本，方便后续实验复现。',requirements:['确认 Git、Python 和 Node.js 可以正常运行。','完成示例项目启动并截图。','提交环境版本清单与启动截图。'],attachment:'开发环境_检查清单.pdf',fileType:'PDF / PNG',statuses:['review','done','pending','review','done','review','pending','done']}
];
let tasks,mode=VARIANT===2?'sent':'received',filter='all',query='',selected=1,pickedFiles=[],uploadTask=null,reviewTarget=null,previousFocus=null;
function resetData(){tasks=baseTasks.map(t=>({...t,records:t.statuses.map((s,i)=>({name:names[i],status:s,note:['review','done','returned'].includes(s)?'已根据任务要求完成，请查收附件。':'',files:['review','done','returned'].includes(s)?[t.title+'_提交.pdf']:[],history:[]}))}));}
resetData();
function mine(t){return t.records.find(r=>r.name==='林同学')||{status:'pending',note:'',files:[],history:[]}}
function receivedTasks(){return tasks.filter(t=>t.records.some(r=>r.name==='林同学'))}
function status(t){return mine(t).status}
function badge(s){return `<span class="badge ${s}"><span class="dot"></span>${states[s]}</span>`}
function countRecords(t,s){return t.records.filter(r=>s.includes(r.status)).length}
function receivedCount(s){return receivedTasks().filter(t=>s.includes(status(t))).length}
function visibleTasks(){return (mode==='received'?receivedTasks():tasks).filter(t=>(filter==='all'||(mode==='received'?status(t)===filter:countRecords(t,[filter])>0))&&(`${t.title} ${t.course}`).toLowerCase().includes(query.toLowerCase()))}
function setMode(m){mode=m;filter='all';query='';if(m==='received'&&!receivedTasks().some(t=>t.id===selected))selected=receivedTasks()[0]?.id;render()}
function setFilter(f){filter=f;renderContent();renderNav()}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function openDialog(id){previousFocus=document.activeElement;$('#'+id).showModal()}
function closeDialog(id){$('#'+id).close();previousFocus?.focus()}
function renderNav(){
 $('#mode-switch').innerHTML=`<button class="${mode==='received'?'active':''}" onclick="setMode('received')">${icon('Inbox',14)} 接收者</button><button class="${mode==='sent'?'active':''}" onclick="setMode('sent')">${icon('Send',14)} 发布者 · 班委</button>`;
 $('#current-name').textContent=mode==='sent'?'陈同学':'林同学';$('#current-avatar').textContent=mode==='sent'?'陈':'林';
 $('#new-task').hidden=mode!=='sent';
 $('#section-tabs').innerHTML=`<button class="tab ${mode==='received'?'active':''}" onclick="setMode('received')">${icon('Inbox',15)} 我收到的 <span class="count">${receivedTasks().length}</span></button><button class="tab ${mode==='sent'?'active':''}" onclick="setMode('sent')">${icon('Send',15)} 我发布的 <span class="count">${tasks.length}</span></button>`;
}
function render(){renderNav();renderContent()}
function filtersHTML(){return ['all','pending','returned','review','done'].map(s=>`<button class="filter ${s===filter?'active':''}" onclick="setFilter('${s}')">${s==='all'?'全部':states[s]}</button>`).join('')}
function searchHTML(){return `<div class="search">${icon('Search')}<input aria-label="搜索任务" placeholder="搜索任务或课程" value="${esc(query)}" oninput="query=this.value;updateSearch()"></div>`}
function updateSearch(){const pos=$('input[aria-label="搜索任务"]').selectionStart;renderContent();const el=$('input[aria-label="搜索任务"]');el?.focus();el?.setSelectionRange(pos,pos)}
function renderContent(){
 const list=visibleTasks();
 if(VARIANT===1)renderInbox(list);else if(VARIANT===2)renderTable(list);else renderBoard(list);
}
function renderInbox(list){
 $('#workspace').innerHTML=`<div class="overview-note">${icon('Inbox',19)}<span>${mode==='received'?`你有 <strong>${receivedCount(['pending','returned'])} 项任务</strong> 需要处理`:`已发布 <strong>${tasks.length} 项任务</strong>，等待查看 ${tasks.reduce((n,t)=>n+countRecords(t,['review']),0)} 份提交`}</span><span class="sep"></span><span class="muted">${mode==='received'?'先完成即将截止的，再处理修改反馈。':'每位同学的提交与反馈独立记录。'}</span></div><div class="inbox-layout"><aside class="inbox-list"><div class="list-tools">${searchHTML()}<div class="filters">${filtersHTML()}</div></div><div>${list.length?list.map(t=>`<button class="task-item ${t.id===selected?'selected':''}" onclick="selectTask(${t.id})"><div class="between"><span class="small muted">${esc(t.course)}</span>${mode==='received'?badge(status(t)):`<span class="badge">${countRecords(t,['review','done'])}/${t.records.length} 已提交</span>`}</div><h3>${esc(t.title)}</h3><div class="task-meta"><span>${mode==='received'?`${t.publisher} 发布`:`${countRecords(t,['review'])} 份待验收`}</span><span class="${t.soon?'deadline-soon':''}">${icon('Clock',12)} ${t.shortDate}</span></div></button>`).join(''):`<div class="empty">${icon('Search',24)}没有匹配的任务<button class="btn ghost" onclick="clearFilter()">清除筛选</button></div>`}</div></aside><article class="detail" id="inline-detail">${detailHTML(tasks.find(t=>t.id===selected)||tasks[0])}</article></div>`;
}
function selectTask(id){selected=id;if(VARIANT===1&&innerWidth>680)renderContent();else showTask(id)}
function clearFilter(){filter='all';query='';renderContent()}
function detailHTML(t){
 const r=mine(t),sent=mode==='sent';
 return `<div class="between"><span class="mono faint">FY-${String(t.id).padStart(4,'0')} · 单人任务</span>${sent?`<span class="badge">${countRecords(t,['done'])===t.records.length?'已收齐':'收集中'}</span>`:badge(r.status)}</div><div style="margin-top:22px" class="task-symbol">${icon('FileText',23)}</div><h2>${esc(t.title)}</h2><span class="badge">${esc(t.course)}</span><div class="detail-meta"><div class="meta-entry"><span class="meta-label">发布人</span><span class="row" style="gap:6px"><span class="avatar" style="width:21px;height:21px;font-size:10px">陈</span>${t.publisher} <span class="faint">· 学委</span></span></div><div class="meta-entry"><span class="meta-label">截止时间</span><span class="${t.soon?'deadline-soon':''}">${t.date}</span></div><div class="meta-entry"><span class="meta-label">接收范围</span><span>指定 ${t.records.length} 人 · 独立提交</span></div><div class="meta-entry"><span class="meta-label">提交格式</span><span>${t.fileType}</span></div></div><div class="rule"></div><div class="prose"><h3>任务说明</h3><p>${esc(t.description)}</p><ol>${t.requirements.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></div><div class="attachment"><span class="file-icon">${icon('FileText',18)}</span><div><div class="name">${esc(t.attachment)}</div><div class="faint small">任务参考附件</div></div><span class="spacer"></span><button class="btn icon-btn ghost" aria-label="预览参考附件" onclick="showReference(${t.id})">${icon('ArrowUpRight',16)}</button></div>${sent?managerPanel(t):studentPanel(t,r)}<div class="history"><span class="dot"></span>陈同学${t.createdLabel||"发布于 11月02日 10:30"}</div>`;
}
function studentPanel(t,r){
 const editable=['pending','returned'].includes(r.status);
 return `<section class="submission-box"><div class="submission-head"><span class="row">${icon('Upload',14)} 我的提交</span>${badge(r.status)}</div><div class="submission-body">${r.status==='returned'?`<div class="feedback"><strong>修改反馈 · 陈同学</strong><br>${esc(r.feedback||t.feedback||'请补充关键步骤与结果说明后重新提交。')}</div>`:''}${r.status==='done'?`<div class="feedback" style="border-color:var(--cat-tools);background:#f2f7f4"><strong>已验收</strong><br>${esc(r.feedback||t.feedback||'已确认收到，任务要求已完成。')}</div>`:''}${r.files.length?`<div class="row" style="font-size:12px;margin-bottom:13px">${icon('FileText',17)} <span>${esc(r.files[0])}</span><span class="spacer"></span><span class="faint">${r.history.length?'刚刚提交':'11月07日'}</span></div>`:''}${r.note?`<p>${esc(r.note)}</p>`:''}${r.status==='pending'?'<p>完成后上传附件或填写说明，再提交给发布者。</p>':r.status==='review'?'<p>提交成功，等待发布者验收。验收前可以撤回修改。</p>':''}<div class="row">${editable?`<button class="btn primary" onclick="openUpload(${t.id})">${icon('Upload',15)} ${r.status==='returned'?'修改并重新提交':'提交任务'}</button>`:r.status==='review'?`<button class="btn" onclick="withdraw(${t.id})">${icon('RotateCcw',14)} 撤回修改</button>`:`<button class="btn" onclick="showSubmission(${t.id})">${icon('FileText',14)} 查看提交记录</button>`}</div><div class="private-note">${icon('LockKeyhole',12)} 提交内容仅你和发布者可见</div></div></section>`;
}
function managerPanel(t){return `<section class="submission-box"><div class="submission-head"><span>提交情况 <strong>${countRecords(t,['review','done'])}/${t.records.length}</strong></span><span class="muted">${countRecords(t,['review'])} 份待验收</span></div><div class="submission-body" style="padding-top:3px;padding-bottom:5px">${t.records.map((r,i)=>`<div class="review-row"><span class="avatar">${r.name[0]}</span><span>${r.name}</span>${badge(r.status)}${r.status==='review'?`<button class="btn small-btn" onclick="openReview(${t.id},${i})">查看并验收 ${icon('ChevronRight',12)}</button>`:r.status==='done'||r.status==='returned'?`<button class="btn small-btn ghost" onclick="openReview(${t.id},${i})">查看记录</button>`:`<span class="spacer"></span><span class="faint small">等待提交</span>`}</div>`).join('')}</div></section>`}
function renderTable(list){
 const allRecords=tasks.flatMap(t=>t.records);
 const stats=mode==='sent'?[['我发布的任务',tasks.length,'项','all'],['待验收',allRecords.filter(r=>r.status==='review').length,'份','review'],['待提交',allRecords.filter(r=>r.status==='pending').length,'份','pending'],['已验收',allRecords.filter(r=>r.status==='done').length,'份','done']]:[['收到的任务',receivedTasks().length,'项','all'],['待提交',receivedCount(['pending']),'项','pending'],['待修改',receivedCount(['returned']),'项','returned'],['已完成',receivedCount(['done']),'项','done']];
 $('#workspace').innerHTML=`<div class="stats-grid">${stats.map(([title,n,unit,f])=>`<button class="stat" onclick="setFilter('${f}')"><span class="stat-label">${title}</span><div class="stat-value">${n}<span>${unit}</span></div></button>`).join('')}</div><div class="toolbar"><div class="filters">${filtersHTML()}</div><div style="width:240px;max-width:240px">${searchHTML()}</div></div><div class="table-wrap"><table class="task-table"><thead><tr><th style="width:36%">任务</th><th>截止时间</th><th>${mode==='sent'?'接收对象':'发布人'}</th><th>${mode==='sent'?'收集进度':'我的状态'}</th><th>${mode==='sent'?'待验收':'提交方式'}</th><th></th></tr></thead><tbody>${list.map(t=>`<tr><td><button class="btn ghost" style="padding:0;justify-content:flex-start;text-align:left;display:block" onclick="showTask(${t.id})"><span class="table-title">${esc(t.title)}</span><span class="table-sub">${esc(t.course)} · FY-${String(t.id).padStart(4,'0')}</span></button></td><td><span class="${t.soon?'deadline-soon':''}">${t.shortDate}</span>${t.soon?'<div class="table-sub deadline-soon">即将截止</div>':''}</td><td>${mode==='sent'?`<span class="row" style="gap:5px">${icon('User',13)} 指定 ${t.records.length} 人</span>`:`<span class="row" style="gap:6px"><span class="avatar" style="width:23px;height:23px">陈</span>${t.publisher}</span>`}</td><td>${mode==='sent'?`<span>${countRecords(t,['review','done'])} <span class="faint">/ ${t.records.length} 人</span></span><div class="progress-track"><div class="progress-fill" style="width:${countRecords(t,['review','done'])/t.records.length*100}%"></div></div>`:badge(status(t))}</td><td>${mode==='sent'?`<span class="${countRecords(t,['review'])?'':'faint'}">${countRecords(t,['review'])} 份</span>`:`<span class="muted">${t.fileType}</span>`}</td><td><button class="btn small-btn ${mode==='sent'?'':'ghost'}" onclick="showTask(${t.id})">${mode==='sent'?'收取任务':'查看'} ${icon('ChevronRight',13)}</button></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty">没有匹配的任务</div></td></tr>'}</tbody></table></div><div class="table-footer"><span>共 ${list.length} 项任务 · 每份提交独立记录</span><span>每人独立提交 · 退回后可重新提交</span></div><div class="tip">${icon(mode==='sent'?'Users':'LockKeyhole',19)}<div><strong>${mode==='sent'?'发给多人，也能逐人收取。':'只看与你有关的任务。'}</strong><br>${mode==='sent'?'同一份要求可以发给指定同学；每人的提交、修改和验收进度各自保留。':'每份提交都保留自己的状态与反馈，其他同学无法查看你的作业。'}</div></div>`;
}
function renderBoard(list){
 $('#workspace').innerHTML=`<div class="toolbar"><div class="row"><span class="small muted">${icon('Columns3',15)} 按${mode==='sent'?'接收进度':'我的状态'}分组</span><span class="faint">·</span><span class="small muted">${list.length} 项任务</span></div><div style="width:250px">${searchHTML()}</div></div><div class="board">${Object.entries(states).map(([s,label])=>{
 const items=list.filter(t=>mode==='received'?status(t)===s:countRecords(t,[s])>0);
 return `<section class="board-column"><div class="column-head"><span class="row" style="gap:7px"><span class="badge ${s}"><span class="dot"></span>${label}</span><span class="count">${items.length}</span></span>${icon('MoreHorizontal',16)}</div><div class="card-stack">${items.map(t=>`<button class="board-card" onclick="showTask(${t.id}${mode==='sent'?`, '${s}'`:''})"><div class="between"><span class="small muted">${esc(t.course)}</span><span class="mono faint">0${t.id}</span></div><h3>${esc(t.title)}</h3><p>${esc(t.description.slice(0,48))}${t.description.length>48?'…':''}</p>${s==='returned'?'<div class="card-note">有新的修改反馈，查看后重新提交</div>':''}<div class="card-footer"><span class="${t.soon?'deadline-soon':''}">${icon('Clock',12)} ${t.shortDate}</span><span>${mode==='sent'?`${countRecords(t,[s])} 人`:`${icon('Paperclip',12)} ${mine(t).files.length||'—'}`}</span></div><div class="card-person"><span class="avatar ${s==='done'?'green':''}">${mode==='sent'?'人':'陈'}</span>${mode==='sent'?`指定 ${t.records.length} 人 · 独立提交`:'陈同学发布'}<span class="spacer"></span>${s==='done'?icon('CircleCheck',14):icon('ArrowUpRight',14)}</div></button>`).join('')||'<div class="column-empty">暂无任务</div>'}</div></section>`}).join('')}</div><div class="board-summary"><span>${mode==='received'?'待提交 → 待验收 → 已完成；收到反馈后进入待修改。':'同一任务可能出现在多列，卡片人数代表该状态下的接收者。'}</span><span>${icon('LockKeyhole',12)} 每人的提交独立可见</span></div>`;
}
function showTask(id,state){selected=id;const t=tasks.find(t=>t.id===id);$('#detail-title').textContent=mode==='sent'?'任务收取':'任务详情';$('#drawer-detail').innerHTML=detailHTML(t);openDialog('detail-dialog');if(state)$('#drawer-detail .submission-box')?.scrollIntoView({block:'start'})}
function showReference(id){const t=tasks.find(t=>t.id===id);$('#reference-title').textContent=t.attachment;$('#reference-body').innerHTML=`<p class="small muted" style="margin-bottom:20px">参考附件内容预览</p><h2 style="font-size:22px">${esc(t.title)}</h2><div class="prose"><p>${esc(t.description)}</p><ol>${t.requirements.map(s=>`<li>${esc(s)}</li>`).join('')}</ol></div><div class="tip">${icon('FileText',18)}<span>此处展示示例附件，用于体验查看参考资料的流程。</span></div>`;openDialog('reference-dialog')}
function openUpload(id){uploadTask=id;pickedFiles=[];const t=tasks.find(t=>t.id===id);$('#upload-task-title').textContent=t.title;$('#upload-form').reset();$('#submission-note').value=mine(t).note||'';$('#upload-error').textContent='';$('#upload-file-hint').textContent=`本任务接受 ${t.fileType} · 单文件不超过 20 MB`;renderPicked();openDialog('upload-dialog')}
function setFiles(fileList){const added=Array.from(fileList);const oversized=added.filter(f=>f.size>20*1024*1024);if(oversized.length){$('#upload-error').textContent='单文件不可超过 20 MB，请重新选择。';return}pickedFiles=[...pickedFiles,...added].filter((f,i,a)=>a.findIndex(x=>x.name===f.name)===i);$('#upload-error').textContent='';renderPicked()}
function renderPicked(){$('#picked-files').innerHTML=pickedFiles.map((f,i)=>`<div class="picked-file">${icon('FileText',15)}<span>${esc(f.name)}</span><span class="spacer"></span><span class="faint small">${(f.size/1024).toFixed(1)} KB</span><button type="button" class="btn icon-btn ghost" aria-label="移除 ${esc(f.name)}" onclick="pickedFiles.splice(${i},1);renderPicked()">${icon('X',13)}</button></div>`).join('')}
function submitTask(e){e.preventDefault();const t=tasks.find(t=>t.id===uploadTask),r=mine(t),note=$('#submission-note').value.trim();if(!pickedFiles.length&&!note){$('#upload-error').textContent='请添加附件或填写提交说明。';return}r.files=pickedFiles.map(f=>f.name);r.note=note;r.status='review';r.history.push({action:'提交任务',note,files:r.files.slice()});closeDialog('upload-dialog');refreshDetails();toast('已提交，等待发布者验收')}
function withdraw(id){const r=mine(tasks.find(t=>t.id===id));r.status='pending';r.history.push({action:'撤回修改'});refreshDetails();toast('已撤回，可以修改后重新提交')}
function refreshDetails(){render();if($('#detail-dialog').open)$('#drawer-detail').innerHTML=detailHTML(tasks.find(t=>t.id===selected))}
function showSubmission(id){const t=tasks.find(t=>t.id===id),r=mine(t);$('#reference-title').textContent='我的提交记录';$('#reference-body').innerHTML=`<h3>${esc(t.title)}</h3><div class="rule"></div>${r.files.map(f=>`<div class="attachment">${icon('FileText',18)}${esc(f)}</div>`).join('')}<p class="prose" style="margin:15px 0">${esc(r.note)}</p>${badge(r.status)}<div class="history">${r.history.length?r.history.map(x=>esc(x.action)).join(' → '):'11月07日提交 → 已验收'}</div>`;openDialog('reference-dialog')}
function openReview(id,i){reviewTarget={id,i};const t=tasks.find(t=>t.id===id),r=t.records[i];$('#review-name').textContent=r.name+'的提交';$('#review-context').textContent=t.title;$('#review-body').innerHTML=`<div class="between"><span class="row"><span class="avatar">${r.name[0]}</span>${r.name}</span>${badge(r.status)}</div><div class="rule"></div><h3>提交说明</h3><p class="prose" style="margin:9px 0 18px">${esc(r.note||'已完成任务，请查收。')}</p>${r.files.map(f=>`<div class="attachment"><span class="file-icon">${icon('FileText',16)}</span><div><div class="name">${esc(f)}</div><span class="small faint">示例提交附件 · 本预览不上传文件</span></div></div>`).join('')}<div class="field" style="margin-top:22px"><label for="review-feedback">${r.status==='review'?'验收反馈':'历史反馈'}</label><textarea id="review-feedback" placeholder="通过时可选填；退回时请说明需要修改的地方。" ${r.status==='review'?'':'readonly'}>${esc(r.feedback||(r.status==='returned'?t.feedback:'')||'')}</textarea><div id="review-error" class="error"></div></div>`;$('#review-actions').innerHTML=r.status==='review'?`<button class="btn" onclick="reviewSubmit(false)">${icon('RotateCcw',14)} 退回修改</button><button class="btn primary" onclick="reviewSubmit(true)">${icon('Check',15)} 确认验收</button>`:`<button class="btn" onclick="closeDialog('review-dialog')">关闭</button>`;openDialog('review-dialog')}
function reviewSubmit(pass){const t=tasks.find(t=>t.id===reviewTarget.id),r=t.records[reviewTarget.i],feedback=$('#review-feedback').value.trim();if(!pass&&!feedback){$('#review-error').textContent='请填写修改意见，让接收者知道如何调整。';return}r.status=pass?'done':'returned';r.feedback=feedback;r.history.push({action:pass?'确认验收':'退回修改',note:feedback});closeDialog('review-dialog');refreshDetails();toast(pass?'已验收，任务标记为完成':'已退回，接收者可查看反馈并重新提交')}
function openNew(){$('#new-form').reset();$('#recipient-list').innerHTML=names.map((n,i)=>`<label class="person-choice"><input type="checkbox" name="recipients" value="${i}" ${i===0?'checked':''}>${n}</label>`).join('');$('#new-error').textContent='';openDialog('new-dialog')}
function createTask(e){e.preventDefault();const title=$('#new-title').value.trim(),description=$('#new-description').value.trim(),recipients=$$('input[name=recipients]:checked').map(x=>+x.value);if(!title||!description||!recipients.length){$('#new-error').textContent='请填写任务标题、说明，并至少选择一位接收者。';return}const due=$('#new-due').value;if(!due){$('#new-error').textContent='请选择截止时间。';return}const [day,time]=due.split('T'),[,m,d]=day.split('-');const t={id:Math.max(...tasks.map(t=>t.id))+1,title,description,course:$('#new-course').value||'班级任务',date:`${m}月${d}日 ${time}`,shortDate:`${m}月${d}日`,due,publisher:'陈同学',createdLabel:'刚刚发布',fileType:$('#new-format').value,requirements:description.split('\n').filter(Boolean),attachment:'任务说明.pdf',records:recipients.map(i=>({name:names[i],status:'pending',note:'',files:[],history:[]}))};tasks.unshift(t);selected=t.id;mode='sent';filter='all';query='';closeDialog('new-dialog');render();toast(`已发布给 ${recipients.length} 位同学，每人独立提交`)}
function restart(){resetData();filter='all';query='';selected=1;$$('dialog[open]').forEach(d=>d.close());render();toast('已恢复示例数据')}
document.addEventListener('click',e=>{if(e.target.tagName==='DIALOG'){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
$('#file-input').addEventListener('change',e=>setFiles(e.target.files));const drop=$('#drop-zone');drop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('dragover')});drop.addEventListener('dragleave',()=>drop.classList.remove('dragover'));drop.addEventListener('drop',e=>{e.preventDefault();drop.classList.remove('dragover');setFiles(e.dataTransfer.files)});
$('#upload-form').addEventListener('submit',submitTask);$('#new-form').addEventListener('submit',createTask);render();
